mapper.sql:
FROM platform_order po
WHERE EXISTS (
    SELECT 1 FROM logistic_channel lc
    INNER JOIN logistic_company company ON company.id = lc.logistic_company_id
    WHERE lc.zh_name = po.logistic_channel_name
      AND company.name LIKE '%威狮%'
)
  AND po.internal_tracking_number IS NOT NULL
  AND TRIM(po.internal_tracking_number) != ''
AND po.shipping_time >= #{startDate}
AND po.shipping_time < #{endExclusive}

    AND po.logistic_channel_name IN
    #{name}

mapper.select:
SELECT DISTINCT po.internal_tracking_number

AND po.internal_tracking_number > #{after}
ORDER BY po.internal_tracking_number
LIMIT #{limit}
